with flattened_attrs as (select id, plan, effective_from, transform(tier_prices, (p, i) -> round(p * tier_limits[i], 2)) as tier_revenue_caps, zip_with(tier_prices, discounts, (p, d) -> round(p * (1 - d), 2)) as net_prices, element_at(tier_prices, 1) as entry_price from price_tiers) select *, ntile(4) over (partition by plan order by entry_price desc, id asc) as entry_price_bucket, avg(entry_price) over (partition by plan order by effective_from asc, id asc rows between 2 preceding and 1 preceding) as entry_price_avg_2_prior, sum(entry_price) over (partition by plan order by entry_price asc, id asc rows between unbounded preceding and current row) as running_entry_price, ntile(4) over (partition by plan order by entry_price desc, id asc) as entry_price_bucket_2 from flattened_attrs
